(()=>{if(!navigator.clipboard)return;document.querySelectorAll(".post-content pre").forEach(e=>{const o=e.querySelector("code");if(!o)return;const s=document.createElement("div");s.className="code-block",e.parentNode.insertBefore(s,e),s.appendChild(e);const t=document.createElement("button");t.type="button",t.className="copy-code",t.textContent="复制",t.setAttribute("aria-label","复制这段代码");const n=document.createElement("span");n.className="sr-only",n.setAttribute("aria-live","polite"),s.append(t,n);let i;t.addEventListener("click",async()=>{window.clearTimeout(i);try{await navigator.clipboard.writeText(o.innerText),t.textContent="已复制",n.textContent="代码已复制到剪贴板",i=window.setTimeout(()=>{t.textContent="复制",n.textContent=""},2200)}catch{t.textContent="请手动复制",n.textContent="复制失败，请手动选择代码"}})})})()